<template>
  <div class="account-page container">
    <section class="account-card card">
      <router-link to="/" class="back-link">← Quay về trang chủ</router-link>
      <header class="account-heading"><span class="font-handwriting">Tài khoản của tôi</span><h1 class="font-serif">Thông tin cá nhân</h1><p>Thông tin này được dùng để điền nhanh khi đặt hàng; bạn vẫn có thể sửa cho từng đơn.</p></header>

      <form class="account-form" @submit.prevent="save">
        <div class="form-group"><label for="full-name">Họ và tên</label><input id="full-name" v-model.trim="form.full_name" required></div>
        <div class="form-group"><label for="email">Email</label><input id="email" :value="authStore.user?.email" disabled></div>
        <div class="form-group"><label for="phone">Số điện thoại</label><input id="phone" v-model.trim="form.phone" type="tel" inputmode="numeric" pattern="0[0-9]{9}" title="Số điện thoại gồm đúng 10 chữ số và bắt đầu bằng số 0" placeholder="09xxxxxxxx"></div>
        <div class="form-group"><label for="address">Địa chỉ mặc định</label><textarea id="address" v-model.trim="form.address" rows="3" placeholder="Số nhà, đường, phường/xã, quận/huyện, tỉnh/thành"></textarea></div>
        <div class="form-group"><label>Ảnh đại diện</label><div class="avatar-picker"><input id="avatar-file" class="sr-only" type="file" accept="image/*" @change="selectAvatar"><label class="file-button" for="avatar-file">Chọn ảnh từ máy</label><button v-if="form.avatar_url" class="remove-avatar" type="button" @click="form.avatar_url=''">Gỡ ảnh</button><small>Hỗ trợ JPG, PNG, WebP (tối đa 2 MB).</small><img v-if="form.avatar_url" :src="form.avatar_url" class="avatar-preview" alt="Ảnh đại diện"></div></div>
        <p v-if="message" :class="success ? 'success' : 'error'">{{ message }}</p>
        <button class="btn btn-primary save-button" :disabled="saving">{{ saving ? 'Đang lưu...' : 'Lưu thay đổi' }}</button>
      </form>

      <section class="password-section"><div><h2>Đổi mật khẩu</h2><p>Dùng mật khẩu mới khi đăng nhập lần sau.</p></div><form class="password-form" @submit.prevent="changePassword"><label>Mật khẩu hiện tại<input v-model="passwordForm.current_password" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input v-model="passwordForm.new_password" type="password" autocomplete="new-password" minlength="6" required></label><label>Nhập lại mật khẩu mới<input v-model="passwordForm.confirm_password" type="password" autocomplete="new-password" minlength="6" required></label><p v-if="passwordMessage" :class="passwordSuccess ? 'success' : 'error'">{{ passwordMessage }}</p><button class="btn btn-secondary" :disabled="changingPassword">{{ changingPassword ? 'Đang đổi...' : 'Đổi mật khẩu' }}</button></form></section>

      <section class="danger-zone"><div><h2>Xóa tài khoản</h2><p>Email này sẽ không thể dùng để đăng ký lại trong 30 ngày. Lịch sử đơn vẫn được lưu để đối soát.</p></div><button type="button" class="delete-account" @click="showDeleteDialog=true">Xóa tài khoản</button></section>
    </section>

    <div v-if="showDeleteDialog" class="dialog-backdrop" @click.self="showDeleteDialog=false"><section class="confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-title"><span class="warning-icon">⚠</span><h2 id="delete-title">Bạn chắc chắn muốn xóa tài khoản?</h2><p>Bạn sẽ được đăng xuất ngay. Email hiện tại không thể đăng ký tài khoản mới trong 30 ngày.</p><div class="dialog-actions"><button type="button" class="cancel-button" @click="showDeleteDialog=false">Quay lại</button><button type="button" class="confirm-delete" :disabled="deleting" @click="deleteAccount">{{ deleting ? 'Đang xóa...' : 'Xác nhận xóa' }}</button></div></section></div>
  </div>
</template>

<script setup>
import { ref } from 'vue';
import { authApi } from '../api';
import { useAuthStore } from '../stores/auth';
const authStore=useAuthStore();
const form=ref({full_name:authStore.user?.full_name||'',phone:authStore.user?.phone||'',address:authStore.user?.address||'',avatar_url:authStore.user?.avatar_url||''});
const saving=ref(false),deleting=ref(false),changingPassword=ref(false),message=ref(''),success=ref(false),passwordMessage=ref(''),passwordSuccess=ref(false),showDeleteDialog=ref(false); const passwordForm=ref({current_password:'',new_password:'',confirm_password:''});
const selectAvatar=event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!file.type?.startsWith('image/')){success.value=false;message.value='Vui lòng chọn đúng tệp ảnh.';return;}if(file.size>2*1024*1024){success.value=false;message.value='Ảnh cần nhỏ hơn hoặc bằng 2 MB.';return;}const reader=new FileReader();reader.onload=()=>{form.value.avatar_url=String(reader.result||'');};reader.onerror=()=>{success.value=false;message.value='Không thể đọc ảnh. Vui lòng thử lại.';};reader.readAsDataURL(file);};
const save=async()=>{if(form.value.phone&&!/^0\d{9}$/.test(form.value.phone)){success.value=false;message.value='Số điện thoại phải gồm đúng 10 chữ số và bắt đầu bằng số 0.';return;}saving.value=true;message.value='';try{const res=await authApi.updateMe(form.value);authStore.setAuth(authStore.token,res.user);success.value=true;message.value='Đã cập nhật thông tin cá nhân.';}catch(e){success.value=false;message.value=e.message||'Không thể cập nhật thông tin.';}finally{saving.value=false;}};
const changePassword=async()=>{passwordMessage.value='';if(passwordForm.value.new_password!==passwordForm.value.confirm_password){passwordSuccess.value=false;passwordMessage.value='Mật khẩu nhập lại chưa khớp.';return;}changingPassword.value=true;try{const result=await authApi.changePassword({current_password:passwordForm.value.current_password,new_password:passwordForm.value.new_password});passwordSuccess.value=true;passwordMessage.value=result.message||'Đã thay đổi mật khẩu.';passwordForm.value={current_password:'',new_password:'',confirm_password:''};}catch(e){passwordSuccess.value=false;passwordMessage.value=e.message||'Không thể thay đổi mật khẩu.';}finally{changingPassword.value=false;}};
const deleteAccount=async()=>{deleting.value=true;try{await authApi.deleteMe();authStore.logout();window.location.assign('/');}catch(e){success.value=false;message.value=e.message||'Không thể xóa tài khoản.';showDeleteDialog.value=false;}finally{deleting.value=false;}};
</script>

<style scoped>
.account-page{padding:3.5rem 1.25rem;display:flex;justify-content:center}.account-card{width:100%;max-width:720px;background:#fff;padding:2.4rem}.account-heading span{color:#bd7006;font-size:1.2rem}.account-heading h1{color:var(--color-primary);margin:.2rem 0 .5rem}.account-heading p{color:var(--color-text-muted);margin:0}.account-form{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1.75rem}.form-group{display:grid;gap:6px}.form-group:nth-child(4),.form-group:nth-child(5),.account-form>p,.save-button{grid-column:1/-1}.form-group label,.password-form label{font-size:.9rem;font-weight:750;color:var(--color-text-main)}input,textarea{display:block;box-sizing:border-box;width:100%;border:1px solid var(--border-color);border-radius:9px;padding:.8rem .85rem;font:inherit;background:#fff}textarea{min-height:92px;resize:vertical;line-height:1.45}input:disabled{background:#f5f2ee;color:#80766d}.avatar-picker{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px;border:1px dashed #d9bbca;border-radius:9px;background:#fff9fb}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.file-button,.remove-avatar{border:0;border-radius:7px;padding:9px 12px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.file-button{background:#b51852;color:#fff}.remove-avatar{background:#fff0f0;color:#a22727}.avatar-picker small{width:100%;color:#786d67;font-size:.78rem}.avatar-preview{width:88px;height:88px;object-fit:cover;border-radius:50%;border:2px solid #eadfd4}.success,.error{margin:0;padding:.7rem 1rem;border-radius:8px}.success{background:#e9f9ef;color:#087a35}.error{background:#fff0f0;color:#a32828}.save-button{justify-self:stretch}.password-section,.danger-zone{margin-top:2.25rem;padding-top:1.5rem;border-top:1px solid var(--border-color)}.password-section h2,.danger-zone h2{font-size:1.05rem;margin:0}.password-section h2{color:var(--color-primary)}.password-section p,.danger-zone p{margin:.35rem 0 0;color:var(--color-text-muted);font-size:.85rem;line-height:1.45}.password-form{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;align-items:end;margin-top:14px}.password-form label{display:grid;gap:6px}.password-form p{grid-column:1/-1}.password-form button{width:max-content}.danger-zone{display:flex;align-items:center;justify-content:space-between;gap:1rem}.danger-zone h2{color:#a32828}.delete-account{flex:0 0 auto;border:1px solid #e7a9a9;border-radius:8px;background:#fff0f0;color:#a32828;padding:.7rem 1rem;font:inherit;font-weight:700;cursor:pointer}.dialog-backdrop{position:fixed;inset:0;display:grid;place-items:center;background:#24181488;z-index:1200;padding:20px}.confirm-dialog{width:min(440px,100%);background:#fff;border-radius:16px;padding:28px;text-align:center;box-shadow:0 18px 50px #0004}.warning-icon{display:grid;place-items:center;width:46px;height:46px;margin:auto;border-radius:50%;background:#fff0f0;color:#a32828;font-size:24px;font-weight:900}.confirm-dialog h2{margin:12px 0 8px;color:#8d143c;font-size:1.25rem}.confirm-dialog p{margin:0;color:#695f59;line-height:1.5}.dialog-actions{display:flex;justify-content:center;gap:10px;margin-top:22px}.cancel-button,.confirm-delete{border:0;border-radius:8px;padding:10px 14px;font:inherit;font-weight:700;cursor:pointer}.cancel-button{background:#f2ede8;color:#4d413a}.confirm-delete{background:#a32828;color:#fff}.confirm-delete:disabled{opacity:.6;cursor:not-allowed}@media(max-width:600px){.account-card{padding:1.5rem}.account-form,.password-form{grid-template-columns:1fr}.form-group:nth-child(4),.form-group:nth-child(5),.account-form>p,.save-button{grid-column:auto}.danger-zone{align-items:flex-start;flex-direction:column}.delete-account,.password-form button{width:100%}}
.back-link{display:inline-block;margin-bottom:1rem;color:var(--color-primary);font-weight:700;text-decoration:none}
</style>
